#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXE 200005

int head[MAXN], to[MAXE], nxt[MAXE], edge_cnt;
int parent[MAXN], order[MAXN], sz[MAXN];

void add_edge(int a, int b) {
    to[edge_cnt] = b;
    nxt[edge_cnt] = head[a];
    head[a] = edge_cnt++;

    to[edge_cnt] = a;
    nxt[edge_cnt] = head[b];
    head[b] = edge_cnt++;
}

int main(void) {
    int n;
    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
        sz[i] = 1;
    }

    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        add_edge(a, b);
    }

    int len = 0;
    order[len++] = 1;
    parent[1] = 0;

    for (int i = 0; i < len; i++) {
        int u = order[i];

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == parent[u]) continue;

            parent[v] = u;
            order[len++] = v;
        }
    }

    for (int i = len - 1; i > 0; i--) {
        int u = order[i];
        sz[parent[u]] += sz[u];
    }

    int ans = n;

    for (int u = 2; u <= n; u++) {
        int diff = n - 2 * sz[u];
        if (diff < 0) diff = -diff;
        if (diff < ans) ans = diff;
    }

    printf("%d\n", ans);

    return 0;
}
